//! Tests for validation groups, field metadata, metrics and async validation.
//!
//! These exercise the extension features generated by `#[derive(RodValidate)]`:
//! `#[rod(group = "...")]` tags, `RodValidate::validate_group`, the generated
//! `RodMetadata` implementation and the combinators built on top of it
//! (`ValidationGroup`, `ValidationMetadata`, `ValidationMetrics`,
//! `AsyncValidator`).

use crate::prelude::*;

#[derive(RodValidate, Clone)]
struct Signup {
    #[rod(
        group = "email-step",
        String {
            length: 5..=10,
        }
    )]
    username: String,
    #[rod(
        group = "email-step",
        String {
            length: 8,
        }
    )]
    password: String,
    #[rod(
        i32 {
            size: 18..=99,
        }
    )]
    age: i32,
}

fn valid_signup() -> Signup {
    Signup {
        username: "kommade".to_string(),
        password: "12345678".to_string(),
        age: 25,
    }
}

#[test]
fn test_validate_group_only_grouped_fields() {
    // Only the grouped `username` is invalid; ungrouped `age` is valid.
    let bad = Signup {
        username: "u1".to_string(),
        password: "12345678".to_string(),
        age: 25,
    };

    // "email-step" sees username + password (grouped) and age (ungrouped),
    // but only username fails.
    let errors = bad.validate_group("email-step").unwrap_err();
    assert_eq!(errors.len(), 1, "{}", errors);
    assert!(errors
        .iter()
        .any(|e| matches!(e, RodValidateError::String(_))), "{}", errors);

    // The grouped username failure does not leak into other groups.
    assert!(bad.validate_group("profile-step").is_ok());
}

#[test]
fn test_validate_group_ungrouped_fields_always_validated() {
    let bad = Signup {
        username: "u1".to_string(),
        password: "12345678".to_string(),
        age: 200,
    };

    // An unknown group still validates the ungrouped `age` field.
    let errors = bad.validate_group("nonexistent-group").unwrap_err();
    assert_eq!(errors.len(), 1, "{}", errors);
    assert!(errors
        .iter()
        .any(|e| matches!(e, RodValidateError::Integer(_))), "{}", errors);
}

#[test]
fn test_validate_group_ok() {
    let good = valid_signup();
    assert!(good.validate_group("email-step").is_ok());
    assert!(good.validate_group("profile-step").is_ok());
}

#[test]
fn test_validate_all_groups() {
    // All fields: username + age fail.
    let bad = Signup {
        username: "u1".to_string(),
        password: "12345678".to_string(),
        age: 200,
    };
    let errors = bad.validate_all_groups().unwrap_err();
    assert_eq!(errors.len(), 2, "{}", errors);

    // validate_all_groups is equivalent to validate_all.
    let list = bad.validate_all().unwrap_err();
    assert_eq!(list.len(), errors.len());
}

#[test]
fn test_validation_group_wrapper() {
    let good = valid_signup();
    let bad = Signup {
        username: "u1".to_string(),
        password: "short".to_string(),
        age: 25,
    };

    assert!(ValidationGroup::new(good.clone())
        .validate_group("email-step")
        .is_ok());
    assert!(ValidationGroup::new(good).validate_all_groups().is_ok());

    let errors = ValidationGroup::new(bad).validate_group("email-step").unwrap_err();
    assert_eq!(errors.len(), 2, "{}", errors); // both email-step fields fail
}

#[test]
fn test_validation_metadata() {
    let fields = Signup::FIELDS;
    assert_eq!(fields.len(), 3);
    assert_eq!(fields[0].name, "username");
    assert_eq!(fields[0].group, Some("email-step"));
    assert!(fields[0].required);
    assert_eq!(fields[1].name, "password");
    assert_eq!(fields[1].group, Some("email-step"));
    assert_eq!(fields[2].name, "age");
    assert_eq!(fields[2].group, None);
    assert!(fields[2].required);

    let signup = Signup {
        username: "kommade".to_string(),
        password: "12345678".to_string(),
        age: 25,
    };
    assert_eq!(signup.fields().len(), 3);
    assert_eq!(signup.required_fields(), vec!["username", "password", "age"]);
    assert_eq!(signup.optional_fields(), Vec::<&str>::new());
    assert_eq!(<Signup as ValidationMetadata>::fields_in_group("email-step").len(), 2);
    assert_eq!(<Signup as ValidationMetadata>::fields_in_group("other").len(), 0);
}

#[test]
fn test_validation_metadata_option_fields_not_required() {
    #[derive(RodValidate)]
    struct Form {
        #[rod(
            Option {
                String {
                    length: 5,
                }
            }
        )]
        nickname: Option<String>,
        #[rod(
            String {
                length: 2,
            }
        )]
        name: String,
        #[rod(skip)]
        ignored: bool,
    }

    let fields = Form::FIELDS;
    assert_eq!(fields.len(), 2); // skipped fields are excluded
    assert_eq!(fields[0].name, "nickname");
    assert!(!fields[0].required);
    assert_eq!(fields[1].name, "name");
    assert!(fields[1].required);

    // Option fields can be None and still pass validation.
    let form = Form {
        nickname: Some("12345".to_string()),
        name: "ab".to_string(),
        ignored: true,
    };
    assert!(form.validate_all().is_ok(), "{}", form.validate_all().unwrap_err());
    assert_eq!(form.required_fields(), vec!["name"]);
    assert_eq!(form.optional_fields(), vec!["nickname"]);
}

#[test]
fn test_validation_metrics() {
    let good = valid_signup();
    let run = good.validate_with_metrics();
    assert_eq!(run.checks, 3);
    assert_eq!(run.failures, 0);

    let bad = Signup {
        username: "u1".to_string(),
        password: "12345678".to_string(),
        age: 200,
    };
    let run = bad.validate_with_metrics();
    assert_eq!(run.checks, 3);
    assert_eq!(run.failures, 2);
    // Wall-clock duration is always non-negative; just make sure it's sane.
    assert!(run.duration_ms < 1_000, "{}", run.duration_ms);
    assert_eq!(Signup::validation_check_count(), 3);
}

#[test]
fn test_validate_any_and_one() {
    let good = Signup {
        username: "kommade".to_string(),
        password: "12345678".to_string(),
        age: 25,
    };
    let bad = Signup {
        username: "u1".to_string(),
        password: "12345678".to_string(),
        age: 25,
    };

    // Passes validation with the identity check.
    assert!(good.validate_any(&[|s: &Signup| s.validate()]).is_ok());
    assert!(bad.validate_any(&[|s: &Signup| s.validate()]).is_err());
    assert!(good.validate_one(&[|s: &Signup| s.validate()]).is_ok());
}

#[test]
fn test_async_validation() {
    fn block_on<F: Future>(fut: F) -> F::Output {
        use std::pin::pin;
        use std::task::{Context, Poll, RawWaker, RawWakerVTable, Waker};

        fn noop_raw_waker() -> RawWaker {
            fn noop(_: *const ()) {}
            fn clone(p: *const ()) -> RawWaker {
                RawWaker::new(p, &VTABLE)
            }
            static VTABLE: RawWakerVTable = RawWakerVTable::new(clone, noop, noop, noop);
            RawWaker::new(std::ptr::null(), &VTABLE)
        }

        // SAFETY: the waker does nothing and never dereferences the pointer.
        let waker = unsafe { Waker::from_raw(noop_raw_waker()) };
        let mut cx = Context::from_waker(&waker);
        let mut fut = pin!(fut);
        loop {
            match fut.as_mut().poll(&mut cx) {
                Poll::Ready(value) => return value,
                Poll::Pending => std::thread::yield_now(),
            }
        }
    }

    let good = valid_signup();
    let bad = Signup {
        username: "u1".to_string(),
        password: "12345678".to_string(),
        age: 200,
    };

    let ok = block_on(good.validate_async());
    assert!(ok.is_ok(), "{}", ok.unwrap_err());

    let err = block_on(bad.validate_async());
    assert_eq!(err.err().unwrap().len(), 2);
}
